const data = getWorkflowStaticData('global');
const now = Date.now();
const ttlMs = 1000 * 60 * 60 * 24 * 7;
if (!data.seen) data.seen = {};
for (const [k, v] of Object.entries(data.seen)) {
  if (!v || (now - v) > ttlMs) delete data.seen[k];
}

const e = $json;
const channel = e.event?.channel || e.channel || '';
const ts = e.event?.ts || e.ts || '';
const eventId = e.event_id || `${channel}:${ts}`;
const subtype = e.event?.subtype || '';
const hasBotId = !!(e.event?.bot_id || e.bot_id);
const userId = e.event?.user || e.user || '';
const ignoreUsers = String($env.SLACK_IGNORE_USER_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
const ignoreThreadReplies = String($env.SLACK_IGNORE_THREAD_REPLIES || 'true').toLowerCase() === 'true';
const isThreadReply = !!(e.event?.thread_ts && e.event?.thread_ts !== e.event?.ts);
const isEdit = subtype === 'message_changed';
const isBotMessage = subtype === 'bot_message' || hasBotId;
const ignoredUser = ignoreUsers.includes(userId);

if (isEdit || isBotMessage || ignoredUser || (ignoreThreadReplies && isThreadReply)) {
  return [];
}

if (data.seen[eventId]) {
  return [];
}

data.seen[eventId] = now;
return [{ json: { ...e, _event_key: eventId } }];

const e = $json.event || $json;
const text = (e.text || '').trim();
const fileName = e.files?.[0]?.name ? `\nFile: ${e.files[0].name}` : '';
const attachmentText = Array.isArray(e.attachments) && e.attachments[0]?.text ? `\nAttachment: ${e.attachments[0].text}` : '';
const enquiryText = `${text}${fileName}${attachmentText}`.trim();

const urgency = /(urgent|asap|outage|down|sev1|critical)/i.test(enquiryText) ? 'high' : (/(soon|today|issue|problem|blocked)/i.test(enquiryText) ? 'medium' : 'low');
const confidence = enquiryText.length > 15 ? 0.78 : 0.45;
const intent = /(invoice|billing|payment|refund)/i.test(enquiryText) ? 'billing' : (/(error|bug|broken|cannot|can't|login|access|vpn|password|it)/i.test(enquiryText) ? 'it_support' : (/(complaint|unhappy|frustrated)/i.test(enquiryText) ? 'complaint' : 'new_enquiry'));
const tags = ['slack', 'enquiry', intent];
if (confidence < 0.5) tags.push('needs_triage');

const channel = e.channel || '';
const ts = e.ts || '';
const permalink = `https://slack.com/archives/${channel}/p${String(ts).replace('.', '')}`;

const fallbackClassification = {
  intent: confidence < 0.5 ? 'other' : intent,
  category: confidence < 0.5 ? 'triage' : intent.replace('_', ' '),
  summary: enquiryText.split('\n')[0].slice(0, 120) || 'Slack enquiry',
  details: enquiryText ? `- Reported in Slack\n- Raw: ${enquiryText.slice(0, 1500)}` : '- Reported in Slack',
  urgency,
  confidence,
  suggested_tags: tags,
  requester_email: '',
  requester_name: ''
};

return [{ json: {
  enquiry_text: enquiryText,
  requester_slack_user_id: e.user || '',
  channel_id: channel,
  ts,
  permalink,
  fallback_classification: fallbackClassification
}}];

const base = $input.first().json || {};
const ai = $input.last().json || {};
const fallback = base.fallback_classification || {};

const pickText = () => {
  if (typeof ai.output_text === 'string' && ai.output_text.trim()) return ai.output_text;
  const c = ai?.output?.[0]?.content;
  if (Array.isArray(c)) {
    const t = c.find(x => x.type === 'output_text' || x.type === 'text');
    if (t?.text) return t.text;
  }
  const msg = ai?.choices?.[0]?.message?.content;
  if (typeof msg === 'string') return msg;
  return '';
};

const extractJson = (raw) => {
  if (!raw) return null;
  try { return JSON.parse(raw); } catch {}
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  if (s >= 0 && e > s) {
    try { return JSON.parse(raw.slice(s, e + 1)); } catch {}
  }
  return null;
};

const parsed = extractJson(pickText()) || {};
const cls = {
  intent: parsed.intent || fallback.intent || 'other',
  category: parsed.category || fallback.category || 'triage',
  summary: parsed.summary || fallback.summary || 'Slack enquiry',
  details: parsed.details || fallback.details || '- Reported in Slack',
  urgency: ['low','medium','high'].includes(parsed.urgency) ? parsed.urgency : (fallback.urgency || 'medium'),
  confidence: Number.isFinite(Number(parsed.confidence)) ? Number(parsed.confidence) : Number(fallback.confidence || 0.4),
  suggested_tags: Array.isArray(parsed.suggested_tags) ? parsed.suggested_tags : (fallback.suggested_tags || ['slack','enquiry']),
  requester_email: typeof parsed.requester_email === 'string' ? parsed.requester_email : (fallback.requester_email || ''),
  requester_name: typeof parsed.requester_name === 'string' ? parsed.requester_name : (fallback.requester_name || '')
};

if (cls.confidence < 0.5) {
  cls.intent = 'other';
  if (!cls.suggested_tags.includes('needs_triage')) cls.suggested_tags.push('needs_triage');
}

return [{ json: { ...base, classification: cls } }];

const c = $json.classification;
const urgencyMap = { low: 1, medium: 2, high: 3 };
const priorityFromUrgency = urgencyMap[c.urgency] || Number($env.FRESHDESK_DEFAULT_PRIORITY || 2);
const tags = Array.from(new Set([...(c.suggested_tags || []), 'slack']));
const body = {
  subject: `[Slack] ${c.summary}`.slice(0, 250),
  description: [
    `Slack permalink: ${$json.permalink}`,
    `Slack channel: ${$json.channel_id}`,
    `Slack user: ${$json.requester_slack_user_id}`,
    `Intent: ${c.intent} (confidence: ${c.confidence})`,
    `Category: ${c.category}`,
    '',
    'Details:',
    c.details
  ].join('\n'),
  priority: priorityFromUrgency,
  status: Number($env.FRESHDESK_DEFAULT_STATUS || 2),
  source: Number($env.FRESHDESK_TICKET_SOURCE || 3),
  tags
};
if ($env.FRESHDESK_GROUP_ID) body.group_id = Number($env.FRESHDESK_GROUP_ID);
if ($env.FRESHDESK_PRODUCT_ID) body.product_id = Number($env.FRESHDESK_PRODUCT_ID);
return [{ json: { ...$json, freshdesk_ticket_body: body } }];
